def largest_divisor(n: int) -> int:
    """
    For a given number n, find the largest number that divides n evenly,
    smaller than n.

    >>> largest_divisor(15)
    5
    """
    if n < 2:
        return 1
    # Find the largest divisor of n that is less than n
    for i in range(2, n):
        if n % i == 0:
            return i
    return n  # Fallback: n itself is the largest divisor (though the problem says < n)
