def fib4(n: int):
    """
    The Fib4 number sequence is defined as:
    fib4(0) = 0
    fib4(1) = 0
    fib4(2) = 2
    fib4(n) = fib4(n-1) + fib4(n-2) + fib4(n-3) + fib4(n-4)

    We use memoization to efficiently compute the n-th element without recursion.
    """
    memo = {0: 0, 1: 0, 2: 2}

    def fib4_helper(n: int) -> int:
        if n in memo:
            return memo[n]
        if n < 0:
            raise ValueError("n must be non-negative")
        if n == 0:
            return 0
        if n == 1:
            return 0
        if n == 2:
            return 2
        result = (
            fib4_helper(n - 1)
            + fib4_helper(n - 2)
            + fib4_helper(n - 3)
            + fib4_helper(n - 4)
        )
        memo[n] = result
        return result

    return fib4_helper(n)
