def is_simple_power(x, n):
    """
    Returns True if x is a simple power of n (i.e., x = n**int),
    and False otherwise.
    """
    if x < 0:
        return False
    if x == 0:
        return True  # 0 is a simple power of any integer (0 = 0**int)

    # Check if x is a perfect power of n
    # We use a loop to find the smallest integer k >= 1 such that n**k >= x
    # and n**k <= x (since we want exact equality)
    k = 1
    while True:
        result = n ** k
        if result > x:
            break
        if result == x:
            return True
        k += 1

    return False
