def find_max(words):
    """Write a function that accepts a list of strings.
    The list contains different words. Return the word with maximum number
    of unique characters. If multiple strings have maximum number of unique
    characters, return the one which comes first in lexicographical order.

    find_max(["name", "of", "string"]) == "string"
    find_max(["name", "enam", "game"]) == "enam"
    find_max(["aaaaaaa", "bb" ,"cc"]) == ""aaaaaaa"
    """
    def count_unique_chars(word):
        return len(set(word))

    def compare(word1, word2):
        if count_unique_chars(word1) != count_unique_chars(word2):
            return count_unique_chars(word1) - count_unique_chars(word2)
        return word1 < word2

    if not words:
        return ""

    max_word = words[0]
    max_count = count_unique_chars(words[0])

    for word in words[1:]:
        if count_unique_chars(word) > max_count:
            max_count = count_unique_chars(word)
            max_word = word

    return max_word
